-- 23-coaches-and-draft-reference. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- 20 coaches + rating snapshots, 1 raw draft board; 0 coach assignments, 0 active drafts, 0 draft picks.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_23;
CREATE TEMP TABLE afl_remaining_23_0 AS SELECT id, league_id, display_name, coach_type, image_url, retired_at FROM coaches WHERE 0;
CREATE TEMP TABLE afl_remaining_23_1 AS SELECT id, season_id, coach_id, version, points_available, special_teams, passing, running, receiving, defending, tackling, physical, conditioning, attributes_json, effective_from FROM coach_season_ratings WHERE 0;
CREATE TEMP TABLE afl_remaining_23_2 AS SELECT id, season_id, label, source_import_batch_id, source_range, board_json FROM draft_board_snapshots WHERE 0;
CREATE TEMP TABLE afl_remaining_23_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_23_check BEFORE INSERT ON afl_remaining_23_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_23_0 i JOIN coaches t ON t.id=i.id WHERE t.league_id IS NOT i.league_id OR t.display_name IS NOT i.display_name OR t.coach_type IS NOT i.coach_type OR t.image_url IS NOT i.image_url OR t.retired_at IS NOT i.retired_at) THEN RAISE(ROLLBACK,'coaches: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_23_0 i JOIN coaches t ON t.league_id=i.league_id AND t.display_name=i.display_name WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'coaches: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_23_1 i JOIN coach_season_ratings t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.coach_id IS NOT i.coach_id OR t.version IS NOT i.version OR t.points_available IS NOT i.points_available OR t.special_teams IS NOT i.special_teams OR t.passing IS NOT i.passing OR t.running IS NOT i.running OR t.receiving IS NOT i.receiving OR t.defending IS NOT i.defending OR t.tackling IS NOT i.tackling OR t.physical IS NOT i.physical OR t.conditioning IS NOT i.conditioning OR t.attributes_json IS NOT i.attributes_json OR t.effective_from IS NOT i.effective_from) THEN RAISE(ROLLBACK,'coach_season_ratings: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_23_1 i JOIN coach_season_ratings t ON t.season_id=i.season_id AND t.coach_id=i.coach_id AND t.version=i.version WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'coach_season_ratings: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_23_2 i JOIN draft_board_snapshots t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.label IS NOT i.label OR t.source_import_batch_id IS NOT i.source_import_batch_id OR t.source_range IS NOT i.source_range OR t.board_json IS NOT i.board_json) THEN RAISE(ROLLBACK,'draft_board_snapshots: existing record differs; no overwrite.') END;
END;
DROP TRIGGER afl_remaining_23_check;
DROP TABLE afl_remaining_23_guard;
DROP TABLE afl_remaining_23_0;
DROP TABLE afl_remaining_23_1;
DROP TABLE afl_remaining_23_2;
RELEASE SAVEPOINT afl_remaining_23;
PRAGMA foreign_key_check;
SELECT 'coaches' AS imported_table,count(*) AS reviewed_records_present FROM coaches t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='4ec48310-d503-5bab-943a-45af456c5e91' AND m.target_table='coaches' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'coach_season_ratings' AS imported_table,count(*) AS reviewed_records_present FROM coach_season_ratings t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='4ec48310-d503-5bab-943a-45af456c5e91' AND m.target_table='coach_season_ratings' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'draft_board_snapshots' AS imported_table,count(*) AS reviewed_records_present FROM draft_board_snapshots t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='4ec48310-d503-5bab-943a-45af456c5e91' AND m.target_table='draft_board_snapshots' AND m.target_id=CAST(t.id AS TEXT));
