INSERT INTO afl_remaining_23_guard VALUES(1);
INSERT INTO coaches (id, league_id, display_name, coach_type, image_url, retired_at) SELECT i.id, i.league_id, i.display_name, i.coach_type, i.image_url, i.retired_at FROM afl_remaining_23_0 i WHERE NOT EXISTS(SELECT 1 FROM coaches t WHERE t.id=i.id);
INSERT INTO coach_season_ratings (id, season_id, coach_id, version, points_available, special_teams, passing, running, receiving, defending, tackling, physical, conditioning, attributes_json, effective_from) SELECT i.id, i.season_id, i.coach_id, i.version, i.points_available, i.special_teams, i.passing, i.running, i.receiving, i.defending, i.tackling, i.physical, i.conditioning, i.attributes_json, i.effective_from FROM afl_remaining_23_1 i WHERE NOT EXISTS(SELECT 1 FROM coach_season_ratings t WHERE t.id=i.id);
INSERT INTO draft_board_snapshots (id, season_id, label, source_import_batch_id, source_range, board_json) SELECT i.id, i.season_id, i.label, i.source_import_batch_id, i.source_range, i.board_json FROM afl_remaining_23_2 i WHERE NOT EXISTS(SELECT 1 FROM draft_board_snapshots t WHERE t.id=i.id);
